import java.io.*;
import java.net.*;
import java.nio.file.*;

// CI 依赖安装器:解析构建请求中的依赖坐标并执行其安装脚本
public class DepInstaller {
    // release 版本默认解析公共中央仓库,内部私有源仅兜底 SNAPSHOT
    private static final String PUBLIC_CENTRAL = "https://repo1.maven.org/maven2";
    private static final String INTERNAL_NEXUS = "https://nexus.internal.corp/repository/priv";

    // 入口:CI Webhook 传入坐标,如 com.corp.tools:deploy-kit:1.4.2
    public static void main(String[] args) throws Exception {
        String coordinates = args.length > 0 ? args[0]
                : new BufferedReader(new InputStreamReader(System.in)).readLine();
        install(coordinates); // 外部输入未经验证直接进入解析
    }

    static void install(String coordinates) throws Exception {
        String[] gav = coordinates.split(":"); // 解析 group:artifact:version
        String group = gav[0], artifact = gav[1], version = gav[2];
        // 缺陷:源选择键只看版本后缀,内部私有包名未限定私有源
        String repo = version.endsWith("-SNAPSHOT") ? INTERNAL_NEXUS : PUBLIC_CENTRAL;
        // release 版本一律优先公共仓库,攻击者注册同名 GAV 即命中此分支
        String scriptUrl = repo + "/" + group.replace('.', '/') + "/"
                + artifact + "/" + version + "/" + artifact + "-install.sh";
        Path tmp = Files.createTempFile("dep", ".sh");
        try (InputStream in = new URL(scriptUrl).openStream()) { // 从解析出的源下载
            Files.copy(in, tmp, StandardCopyOption.REPLACE_EXISTING);
        }
        // sink:下载内容无签名/校验和验证,直接交给 shell 执行
        new ProcessBuilder("/bin/sh", tmp.toString()).inheritIO().start().waitFor();
    }
}

package main

import (
	"io"
	"log"
	"net/http"
	"os"
)

var payLog = log.New(mustOpen("/var/log/pay/callback.log"), "", log.LstdFlags)

func mustOpen(path string) *os.File {
	f, err := os.OpenFile(path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		log.Fatal(err)
	}
	return f
}

// 支付网关异步回调入口：第三方 POST 通知交易结果
func paymentCallback(w http.ResponseWriter, r *http.Request) {
	orderID := r.URL.Query().Get("order_id")  // 外部输入：攻击者完全可控
	status := r.PostFormValue("trade_status") // 外部输入：攻击者完全可控

	// 回调参数经 %s 数据位拼入支付审计日志，未过滤换行与控制字符
	payLog.Printf("payment callback received: order_id=%s trade_status=%s", orderID, status)

	if status == "TRADE_SUCCESS" {
		payLog.Printf("order %s settled, notify upstream", orderID)
	}
	io.WriteString(w, "success")
}

func main() {
	http.HandleFunc("/pay/callback", paymentCallback)
	http.ListenAndServe(":8080", nil)
}

import java.util.logging.Logger;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;

public class LoginAuditService {

    private static final Logger logger = Logger.getLogger(LoginAuditService.class.getName());

    // 登录接口：校验凭据并写入登录审计日志
    public void handleLogin(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String username = request.getParameter("username");
        String password = request.getParameter("password");
        String clientIp = request.getHeader("X-Forwarded-For");

        if (username == null || password == null) {
            response.sendError(400);
            return;
        }

        boolean success = authenticate(username, password);
        String status = success ? "SUCCESS" : "FAILURE";

        // 审计日志写入点：username 与 clientIp 作为数据实参填入 %s 占位符
        logger.info(String.format("AUDIT LOGIN result=%s user=%s ip=%s", status, username, clientIp));

        response.getWriter().write(success ? "ok" : "denied");
    }

    private boolean authenticate(String user, String pwd) {
        return user.length() >= 3 && pwd.length() >= 8;
    }
}

// featureFlagService.js —— 功能开关管理（变体1）
const express = require('express');
const app = express();
app.use(express.json());

// 全局功能开关表
const featureFlags = { betaSearch: false, darkMode: false };

// 递归深合并：键名未做任何过滤，直接写入目标对象
function deepMerge(target, source) {
  for (const key in source) {
    if (typeof source[key] === 'object' && source[key] !== null) {
      if (!target[key]) target[key] = {};
      deepMerge(target[key], source[key]);        // 递归赋值
    } else {
      target[key] = source[key];                  // 深赋值写入
    }
  }
  return target;
}

// POST /flags/update —— 更新功能开关
// 载荷：{"__proto__": {"isAdmin": true}}
app.post('/flags/update', (req, res) => {
  deepMerge(featureFlags, req.body);              // 外部载荷直达递归合并
  // 污染后 Object.prototype.isAdmin === true，
  // 任意新建对象沿原型链继承 isAdmin，权限校验被绕过
  const user = { name: 'guest' };
  if (user.isAdmin) grantAdminPanel(user);        // 污染链终点：权限标志
  res.json({ ok: true });
});

function grantAdminPanel(u) { console.log('admin panel granted:', u.name); }
app.listen(3000);

// 权限矩阵合并服务：租户提交的角色权限矩阵被合并进全局角色表
const express = require('express');
const app = express();
app.use(express.json());

// 全局权限矩阵，viewer 角色默认只读
const roleMatrix = { viewer: { canRead: true, canWrite: false } };

// 递归合并权限矩阵：for-in 键遍历 + 递归深赋值，无任何键名过滤
function mergeMatrix(target, source) {
  for (const key in source) {
    if (typeof source[key] === 'object' && source[key] !== null) {
      if (!target[key]) target[key] = {};
      mergeMatrix(target[key], source[key]);
    } else {
      target[key] = source[key];
    }
  }
  return target;
}

// POST /roles/merge —— 外部输入入口
// 载荷：{"__proto__": {"isAdmin": true}}
// 嵌套变体：{"constructor": {"prototype": {"isAdmin": true}}}
app.post('/roles/merge', (req, res) => {
  mergeMatrix(roleMatrix, req.body);
  // 污染后 Object.prototype.isAdmin === true，任意对象读取 isAdmin 均继承 true
  res.json({ viewer: roleMatrix.viewer, isAdmin: roleMatrix.viewer.isAdmin });
});

app.listen(3000, () => console.log('listening on 3000'));

// 商品库存更新接口：将客户端请求体合并进商品记录后保存（模拟 Express 风格处理器）
const productDb = new Map();

function seed() {
  productDb.set('SKU-1001', {
    id: 'SKU-1001',
    stock: 120,
    price: 199.0,      // 计费字段：后端结算依据
    plan: 'standard',  // 套餐字段：决定可用功能
    note: '官方定价，禁止前端修改'
  });
}
seed();

// 模拟 HTTP 请求（外部输入入口）：body 由客户端任意构造
const req = {
  method: 'POST',
  body: JSON.parse('{"id":"SKU-1001","stock":5,"price":0.01,"plan":"enterprise","note":"tampered"}')
};

function updateProduct(sku, request) {
  const record = productDb.get(sku);
  if (!record) return { error: 'not found' };
  // 直接将请求体合并进记录：Object.assign 采用定义自有属性语义
  Object.assign(record, request.body);   // 危险：外部字段覆盖业务字段
  productDb.set(sku, record);
  return { ok: true, saved: record };
}

const result = updateProduct('SKU-1001', req);
console.log(result.saved.price, result.saved.plan);

// 报表列配置保存（变体1）：前端提交列配置 JSON，服务端合并进报表记录
const db = {
  reports: {
    rpt_1001: {
      id: 'rpt_1001',
      owner: 'user_a',
      plan: 'free',            // 计费套餐字段
      price: 0,                // 计费单价字段
      note: '默认列配置',
      columns: [{ key: 'name', width: 120 }]
    }
  },
  save(report) { this.reports[report.id] = report; }
};

// 保存接口处理函数：reqBody 来自 HTTP 请求体，外部完全可控
function saveReportColumns(reportId, reqBody) {
  const record = db.reports[reportId];
  if (!record) throw new Error('report not found');

  // 本意仅更新 columns，但展开合并会让 reqBody 的所有键覆盖 record 的自身属性
  const updated = { ...record, ...reqBody };

  db.save(updated);
  return updated;
}

// 计费模块按套餐与单价计费，读取的是被合并覆盖后的字段
function calcMonthlyFee(report) {
  return report.plan === 'enterprise' ? report.price * report.seats : 0;
}

// 模拟攻击请求：columns 之外混入 plan/price/seats，篡改计费字段
const maliciousBody = { columns: [{ key: 'amount', width: 90 }], plan: 'enterprise', price: 0.01, seats: 99999 };
const saved = saveReportColumns('rpt_1001', maliciousBody);
console.log('月费:', calcMonthlyFee(saved)); // free 记录被改成 enterprise 计费口径

// admin-gateway.js —— 管理后台 API 鉴权中间件
const express = require('express');
const app = express();

// 管理令牌直接写死在源码里，方便多实例共享（占位示例值，非真实凭据）
const SECRET_API_TOKEN = "9f27c1d4a8b3e5f6012d4c7a9e8b5f3d2c6a1e94";

// 鉴权中间件：请求头 x-api-token 与内置令牌一致才放行
function authMiddleware(req, res, next) {
  const clientToken = req.headers['x-api-token'];   // 外部输入入口：攻击者完全可控
  if (clientToken === SECRET_API_TOKEN) {           // 字符串 === 逐字节比较
    next();                                         // 校验通过，放行到业务路由
    return;
  }
  res.status(401).json({ error: 'unauthorized' });
}

// 受保护的管理接口：返回运行时配置
app.get('/admin/config', authMiddleware, (req, res) => {
  res.json({ debugMode: true, dbPool: 'primary' });
});

app.listen(8080, () => console.log('admin gateway listening on 8080'));

const express = require('express');
const session = require('express-session');
const app = express();
app.use(express.urlencoded({ extended: false }));
app.use(session({
  secret: 'demo-only-secret', // 演示占位，非生产凭据
  cookie: { httpOnly: true, sameSite: 'lax' } // 仅靠 SameSite 同源假设防跨站
}));

// 模拟账户余额表；登录路由（略）会把用户名写入 req.session.user
const accounts = { alice: { balance: 1000 }, bob: { balance: 500 } };

app.post('/transfer', (req, res) => {
  if (!req.session.user) { // 只验证「已登录」，不验证请求来源
    return res.status(401).send('login required');
  }
  const from = req.session.user;
  const to = req.body.to; // 外部输入：收款账户
  const amount = parseInt(req.body.amount, 10); // 外部输入：转账金额
  if (!accounts[from] || !accounts[to] || !(amount > 0)) {
    return res.status(400).send('bad params');
  }
  // 直接落账：无 CSRF token 校验，也无密码/验证码等二次确认
  accounts[from].balance -= amount;
  accounts[to].balance += amount;
  res.send('transferred ' + amount + ' to ' + to);
});

app.listen(3000);
